head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    requires("uiplugin.popup"); //팝업을 사용하기 위해 반드시 포함되어야 한다.
    //dataList1.getRowJSON와 같은 API 호출 시 반환 객체.
    var rowJSON = {
        "addr": "서울시",
        "name": "손예진",
        "rowStatus": "R"
    };
    //popup에 넘길 data객체.
    var dataObj = {
        type: "json", // 데이터 타입. "xml","string","json","array"
        data: rowJSON, // 전달 데이터 객체.
        name: "rowObj" // 변수명. popup에서 $w.getParameter( "rowObj" )로 깨내올 수 있다.
    };
    var options = {
        id: "popup1",
        type: "window",
        width: "230px",
        height: "250px",
        top: "130px",
        left: "200px",
        popupName: "openPopup1",
        modal: true,
        useIFrame: true,
        frameMode: 'wframe',
        resizable: true,
        status: true,
        menubar: false,
        scrollbars: false,
        title: false,
        useModalStack: true,
        alwaysOnTop: true,
        dataObject: dataObj
    };
    $w.openPopup("popup_wframe_onpageload_WPFF-80_(WSQ-3230)_sub.xml", options);
};
scwin.checkElement = function(id) {
    if (WebSquare.wUnit.getDomById(id)) {
        return true;
    }
    return false
}
scwin.checkVal = function() {
    return window.log == true;
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. main샘플 실행 후 '팝업OPEN'버튼을 클릭한다.
    //1. After running the main sample, click the 'Pop-up OPEN' button.
    //Verify step 1. A true value is returned and shown.(Previously a false value is returned)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkElement('popup1')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 알림창의 '확인'버튼을 클릭한다.
    //2. Click the 'OK' button in the notification window.
    //Verify step 2. The WFRAME value is displayed in the openPopup1 window.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#popup1_content').text() == 'WFRAME'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 22-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
